using Ruth.Modules.Finance.Contracts.Gateways;
using Ruth.SharedKernel.Messaging;

namespace Ruth.Modules.Finance.Contracts.PaymentMethods;

/// <summary>Command to exchange a hosted payment token at a gateway and persist a tokenized saved payment method.</summary>
/// <param name="PersonId">Constituent or Business organization Person identifier.</param>
/// <param name="FinancialGatewayId">Target financial gateway configuration identifier.</param>
/// <param name="HostedPaymentToken">Single-use token generated by the browser hosted tokenizer.</param>
/// <param name="MethodKind">Payment instrument kind.</param>
/// <param name="DisplayName">Optional friendly nickname for the saved instrument.</param>
/// <param name="BillingName">Optional cardholder or account holder name.</param>
/// <param name="BillingEmail">Optional billing email.</param>
/// <param name="MaskedLast4Hint">Optional last-4 digits hint from hosted tokenizer.</param>
/// <param name="CardBrandHint">Optional card brand hint from hosted tokenizer.</param>
/// <param name="ExpiryMonthHint">Optional card expiration month (1..12).</param>
/// <param name="ExpiryYearHint">Optional four-digit card expiration year.</param>
/// <param name="HouseholdId">Optional shared Household identifier.</param>
/// <param name="SetAsDefault">Whether to mark this method as default for the constituent.</param>
public sealed record VaultSavedPaymentMethodCommand(
    Guid PersonId,
    Guid FinancialGatewayId,
    string HostedPaymentToken,
    PaymentMethodKind MethodKind,
    string? DisplayName = null,
    string? BillingName = null,
    string? BillingEmail = null,
    string? MaskedLast4Hint = null,
    string? CardBrandHint = null,
    int? ExpiryMonthHint = null,
    int? ExpiryYearHint = null,
    Guid? HouseholdId = null,
    bool SetAsDefault = true
) : ICommand<SavedPaymentMethodResponse>;
